import{_ as s,o as a,c as n,a6 as t}from"./chunks/framework.DMOj2-2K.js";const u=JSON.parse('{"title":"8. Share and ship","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/08-share-and-ship.md","filePath":"tutorial/08-share-and-ship.md"}'),i={name:"tutorial/08-share-and-ship.md"};function o(p,e,l,r,c,d){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_8-share-and-ship" tabindex="-1">8. Share and ship <a class="header-anchor" href="#_8-share-and-ship" aria-label="Permalink to &quot;8. Share and ship&quot;">​</a></h1><p><strong>Goal:</strong> give your product owner and QA team an up-to-date description of the app straight from the code, then build the Helpdesk for production and run it.</p><p>The code is done. In this chapter you don&#39;t change a single <code>.clb</code> file.</p><h2 id="explaining-the-app-to-the-team" tabindex="-1">Explaining the app to the team <a class="header-anchor" href="#explaining-the-app-to-the-team" aria-label="Permalink to &quot;Explaining the app to the team&quot;">​</a></h2><p>Software teams spend a lot of time keeping documents in sync with code: &quot;what can users do on this screen?&quot;, &quot;what are the validation rules?&quot;, &quot;what has QA covered?&quot;. Cluub answers these questions from the code itself, so the answer is never out of date.</p><h3 id="for-the-product-owner" tabindex="-1">For the product owner <a class="header-anchor" href="#for-the-product-owner" aria-label="Permalink to &quot;For the product owner&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> po</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Helpdesk — Customers submit support tickets, AI triages them, agents resolve them</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## For product owners: what users can do</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Home screen (\`/\`)</span></span>
<span class="line"><span>Customers describe their problem and get a ticket number</span></span>
<span class="line"><span>Users can:</span></span>
<span class="line"><span>- Send a support ticket</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### ImportEmail screen (\`/import\`)</span></span>
<span class="line"><span>Agents paste a customer email and AI turns it into a ticket</span></span>
<span class="line"><span>Users can:</span></span>
<span class="line"><span>- Create a ticket from a pasted email</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Queue screen (\`/queue\`)</span></span>
<span class="line"><span>Agents see every ticket that still needs work, most urgent first</span></span>
<span class="line"><span>Users can:</span></span>
<span class="line"><span>- Start working on a ticket</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### TicketDetail screen (\`/tickets/{id}\`)</span></span>
<span class="line"><span>Everything about one ticket; agents start and resolve it here</span></span>
<span class="line"><span>Users can:</span></span>
<span class="line"><span>- Start working on this ticket</span></span>
<span class="line"><span>- Resolve the ticket and record how</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>## AI-powered features</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- TriageService: Decide how urgent a ticket is</span></span>
<span class="line"><span>- TriageService: Decide which team should handle a ticket</span></span>
<span class="line"><span>- TriageService: Summarize a ticket in one sentence for busy agents</span></span>
<span class="line"><span>- TriageService: Find the customer, subject and problem in a pasted email</span></span></code></pre></div><p>Look familiar? Every sentence is one of your <code>about</code> lines. The app&#39;s description comes from <code>app.clb</code>, each screen&#39;s from its page, each &quot;Users can&quot; bullet from a page action, and the AI features are every service action that contains <code>ask ai</code>. This is why the tutorial asked you to write <code>about</code> lines all along, and why <code>cluub check</code> suggests one when it&#39;s missing (W104).</p><h3 id="for-qa" tabindex="-1">For QA <a class="header-anchor" href="#for-qa" aria-label="Permalink to &quot;For QA&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qa</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Helpdesk — Customers submit support tickets, AI triages them, agents resolve them</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## For QA: what is tested</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 13 hand-written tests, 48 generated tests (run \`cluub test\`).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Hand-written tests</span></span>
<span class="line"><span>- the api creates a ticket _(tests/api.test.clb:1)_</span></span>
<span class="line"><span>- the api rejects a bad email address _(tests/api.test.clb:6)_</span></span>
<span class="line"><span>- the api says when a ticket does not exist _(tests/api.test.clb:11)_</span></span>
<span class="line"><span>- a new ticket is open and triaged _(tests/tickets.test.clb:1)_</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Generated tests</span></span>
<span class="line"><span>- Ticket: can be created with valid values</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### Edge cases to explore manually</span></span>
<span class="line"><span>- TicketService.importEmail: check &quot;Paste the customer&#39;s email first&quot; appears when NOT (rawEmail is not empty)</span></span>
<span class="line"><span>- TicketService.start: check &quot;This ticket is already resolved&quot; appears when the error case happens</span></span>
<span class="line"><span>- TicketService.resolve: check &quot;Please describe how you solved the problem&quot; appears when NOT (resolution is not empty)</span></span>
<span class="line"><span>- TicketService.resolve: check &quot;The resolution must be at least 10 characters&quot; appears when NOT (resolution.count is at least 10)</span></span>
<span class="line"><span>- TicketService.resolve: check &quot;This ticket is already resolved&quot; appears when the error case happens</span></span></code></pre></div><p>QA gets the list of every test (the generated ones are plain Cluub they can read, as you saw in chapter 7) and a checklist of business rules to try by hand, built from your <code>require</code> and <code>fail</code> lines. Run <code>cluub test</code> before <code>cluub explain --for qa</code> so the generated list is current.</p><h3 id="for-business-analysts-and-developers" tabindex="-1">For business analysts and developers <a class="header-anchor" href="#for-business-analysts-and-developers" aria-label="Permalink to &quot;For business analysts and developers&quot;">​</a></h3><p>Two more roles are built in. <code>cluub explain --for ba</code> lists every model field with its rules, a table of business rules and the api endpoints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Business rules</span></span>
<span class="line"><span>| Where | Rule | Message shown |</span></span>
<span class="line"><span>|---|---|---|</span></span>
<span class="line"><span>| TicketService.importEmail | rawEmail is not empty | Paste the customer&#39;s email first |</span></span>
<span class="line"><span>| TicketService.start | (error case) | This ticket is already resolved |</span></span>
<span class="line"><span>| TicketService.resolve | resolution is not empty | Please describe how you solved the problem |</span></span>
<span class="line"><span>| TicketService.resolve | resolution.count is at least 10 | The resolution must be at least 10 characters |</span></span>
<span class="line"><span>| TicketService.resolve | (error case) | This ticket is already resolved |</span></span></code></pre></div><p><code>cluub explain --for dev</code> shows the architecture: which page uses which api, which api uses which service, and where each store saves. Plain <code>cluub explain</code> prints all four sections.</p><h3 id="sharing-the-output" tabindex="-1">Sharing the output <a class="header-anchor" href="#sharing-the-output" aria-label="Permalink to &quot;Sharing the output&quot;">​</a></h3><p>The output is Markdown. Write it to a file to put in a wiki, a pull request or a ticket:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> explain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> QA.md</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ Wrote QA.md</span></span></code></pre></div><p>A good habit is to regenerate it in CI on every merge, so the team&#39;s overview is always the current truth. See <a href="/guide/team">POs, BAs, QAs &amp; AI</a>.</p><h2 id="build-for-production" tabindex="-1">Build for production <a class="header-anchor" href="#build-for-production" aria-label="Permalink to &quot;Build for production&quot;">​</a></h2><p><code>cluub dev</code> is for development: it recompiles and reloads on every save. For production, compile once. Stop <code>cluub dev</code> (Ctrl+C) and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ Built in 12.4ms → dist/ (4 pages · 1 apis · 2 services · 2 models)</span></span></code></pre></div><p><code>cluub build</code> refuses to build if there&#39;s any compile error, so a broken project never reaches production. It writes plain JavaScript into <code>dist/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dist/</span></span>
<span class="line"><span>├── server.js                  # your backend: api, services, stores, AI</span></span>
<span class="line"><span>├── start.mjs                  # runs the built app with plain Node</span></span>
<span class="line"><span>├── runtime/                   # the server side of the Cluub runtime</span></span>
<span class="line"><span>├── compiler/diagnostics.js</span></span>
<span class="line"><span>└── public/</span></span>
<span class="line"><span>    ├── index.html</span></span>
<span class="line"><span>    └── _cluub/</span></span>
<span class="line"><span>        ├── app.client.js      # your pages, components and layout</span></span>
<span class="line"><span>        ├── boot.js</span></span>
<span class="line"><span>        ├── theme.css</span></span>
<span class="line"><span>        ├── compiler/diagnostics.js</span></span>
<span class="line"><span>        └── runtime/           # the browser side of the runtime (ai, client, core, errors, messages)</span></span></code></pre></div><p>There are no third-party packages anywhere in that folder, and it doesn&#39;t need Cluub installed to run. See the <a href="/reference/cli#what-cluub-build-produces">CLI reference</a>.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ Running at http://localhost:3000</span></span></code></pre></div><p>Open <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>. It&#39;s the same app, without live reload. <code>cluub start</code> picks its port from <code>--port</code>, then the <code>PORT</code> environment variable, then the <code>port</code> in <code>app.clb</code>, and finally 3000:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8080</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cluub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>Because <code>dist/</code> is self-contained, a server doesn&#39;t need the <code>cluub</code> command at all. Plain Node runs it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/start.mjs</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Running at http://localhost:3000</span></span></code></pre></div><p>A few things to know before you put it on a real server:</p><ul><li><p><strong>Data.</strong> The <code>Tickets</code> store still saves to <code>storage/tickets.json</code> in the project folder, so tickets survive restarts. Back that file up. A JSON file is fine for a small team; for more, the store is the one place you&#39;d change.</p></li><li><p><strong>Secrets.</strong> Put <code>ANTHROPIC_API_KEY</code> (or your provider&#39;s key) in <code>.env</code> on the server or in the environment. It&#39;s never part of <code>dist/</code>, and never sent to the browser.</p></li><li><p><strong>Errors.</strong> In production, users never see internal details. Unexpected errors return <em>&quot;Something went wrong on the server.&quot;</em>, and AI problems, such as a missing key or a provider outage, return <em>&quot;The AI service is not available right now. Please try again.&quot;</em> The details go to the server log:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ TicketApi.importEmail: No API key for claude. Run &quot;cluub ai set claude&quot; (or add ANTHROPIC_API_KEY=... to .env). Never put keys in code.</span></span>
<span class="line"><span>POST /api/tickets/import 502 5ms</span></span></code></pre></div><p>Ticket triage still degrades quietly thanks to the <code>try ... catch</code> from chapter 6.</p></li><li><p><strong>Deploying.</strong> Anywhere Node 18+ runs: run <code>cluub build</code>, then copy the project (or at least <code>dist/</code>, <code>.env</code> and <code>storage/</code>) to the server and run <code>node dist/start.mjs</code> or <code>cluub start</code>.</p></li></ul><h2 id="checkpoint" tabindex="-1">Checkpoint <a class="header-anchor" href="#checkpoint" aria-label="Permalink to &quot;Checkpoint&quot;">​</a></h2><ul><li><code>cluub explain --for po</code> lists four screens and four AI-powered features, using your <code>about</code> lines.</li><li><code>cluub explain --for qa</code> reports 13 hand-written and 48 generated tests.</li><li><code>cluub build</code> prints <code>✓ Built ... → dist/ (4 pages · 1 apis · 2 services · 2 models)</code>.</li><li><code>cluub start</code> prints <code>✓ Running at http://localhost:3000</code> (and <code>node dist/start.mjs</code> prints <code>Running at http://localhost:3000</code>), and the app works as before, with your saved tickets.</li><li><code>cluub check</code> prints <code>✓ No errors</code> and <code>cluub test</code> prints <code>61 passed</code>.</li></ul><h2 id="what-you-built" tabindex="-1">What you built <a class="header-anchor" href="#what-you-built" aria-label="Permalink to &quot;What you built&quot;">​</a></h2><p>In about 240 lines of Cluub (not counting tests) you have a full-stack app with:</p><ul><li>a validated data model and a persisted store,</li><li>business rules with clear error messages,</li><li>six HTTP endpoints with automatic input checking,</li><li>four pages, a component and a layout, with no frontend plumbing,</li><li>AI classification, summarization and structured extraction that degrade gracefully,</li><li>61 tests and team documentation that can&#39;t go out of date.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Some ideas to keep going, using only what you&#39;ve learned:</p><ul><li><strong>Reopen tickets.</strong> Add <code>action reopen(id: text)</code> to <code>TicketService</code> that sets a resolved ticket back to <code>open</code>, a <code>post reopen</code> route, and a <strong>Reopen</strong> button on the detail page. Then write a UI test for it.</li><li><strong>Filter the queue.</strong> Add <code>state category = &quot;all&quot;</code> and a <code>select category, options [...]</code> to the queue page, and a <code>get</code> route with a <code>with category: text</code> query parameter.</li><li><strong>Suggest a reply.</strong> Add a <code>suggestReply</code> action to <code>TriageService</code> with plain <code>ask ai</code>, and show the draft on the detail page with a <strong>Suggest a reply</strong> button.</li><li><strong>Restyle it.</strong> Add a <code>theme.css</code> with your colors (see <a href="/guide/frontend#look-and-feel">Pages &amp; components</a>).</li><li><strong>Let AI do it.</strong> Try <code>cluub make &quot;add a reopen button to the ticket detail page&quot;</code>. The AI gets the language reference and your project, and Cluub only writes the files if the whole project still compiles. Then run <code>cluub test</code>.</li></ul><p>A few things are deliberately not in this tutorial because Cluub 0.1 doesn&#39;t have them yet: user accounts and login (anyone who can open the queue can resolve tickets, so keep it on an internal network), a database other than JSON files, and file uploads such as screenshots on tickets. Check the <a href="/reference/roadmap">roadmap</a> for what&#39;s coming.</p><p>To go deeper, read the <a href="/reference/language">language reference</a>, the guides on <a href="/guide/data">models &amp; data</a>, <a href="/guide/backend">services &amp; APIs</a>, <a href="/guide/frontend">pages &amp; components</a> and <a href="/guide/ai">AI</a>, or start a new project with <code>cluub new my-app</code> and see how the <code>app</code> template does things.</p><p>Congratulations, you&#39;ve built and shipped a Cluub app.</p>`,50)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
